// usage: node shot.mjs <html> <out.png> [w] [h] [waitMs] [dpr] [rm=0|1] [moves="x,y;x,y;..."] [click="x,y"]
import { createRequire } from 'node:module';
const require = createRequire('<HOME>/.local/lib/node_modules/@playwright/mcp/node_modules/');
const { chromium } = require('playwright-core');
const [html, out, w = '1400', h = '850', wait = '2500', dpr = '1', rm = '0', moves = '', click = ''] = process.argv.slice(2);
const browser = await chromium.launch({ executablePath: '<HOME>/.cache/ms-playwright/chromium-1223/chrome-linux/chrome', headless: true, args: ['--no-sandbox', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'] });
