#veil{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse 78% 72% at 50% 56%,rgba(0,0,0,0) 42%,rgba(0,0,0,.42) 78%,rgba(0,0,0,.8) 100%)}
</style>
</head>
<body>
<canvas id="scene" role="img" aria-label="A steaming bowl of vegan ramen in a dark ceramic bowl"></canvas>
<div id="veil"></div>
<script>
(() => {
'use strict';
/* ---------------------------------------------------------------- utils */
const TAU = Math.PI * 2, PI = Math.PI;
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const lerp = (a, b, t) => a + (b - a) * t;
const sm = t => t * t * (3 - 2 * t);
const mulberry = seed => () => {
  seed |= 0; seed = seed + 0x6D2B79F5 | 0;
  let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
  t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
  return ((t ^ t >>> 14) >>> 0) / 4294967296;
};
const rnd = mulberry(90210);
const rr = (a, b) => a + (b - a) * rnd();

/* value noise (3d) */
const perm = new Uint8Array(512);
{
  const p = []; for (let i = 0; i < 256; i++) p[i] = i;
  const r = mulberry(1234);
  for (let i = 255; i > 0; i--) { const j = Math.floor(r() * (i + 1)); const t = p[i]; p[i] = p[j]; p[j] = t; }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
}
const h3 = (x, y, z) => perm[(x + perm[(y + perm[z & 255]) & 255]) & 255] / 255;
function noise3(x, y, z) {
  const xi = Math.floor(x), yi = Math.floor(y), zi = Math.floor(z);
  const u = sm(x - xi), v = sm(y - yi), w = sm(z - zi);
  const X = xi & 255, Y = yi & 255, Z = zi & 255;
  const a = lerp(lerp(h3(X, Y, Z), h3(X + 1, Y, Z), u), lerp(h3(X, Y + 1, Z), h3(X + 1, Y + 1, Z), u), v);
  const b = lerp(lerp(h3(X, Y, Z + 1), h3(X + 1, Y, Z + 1), u), lerp(h3(X, Y + 1, Z + 1), h3(X + 1, Y + 1, Z + 1), u), v);
  return lerp(a, b, w) * 2 - 1;
}

/* ------------------------------------------------------------- geometry */
/* Scene units: bowl rim radius = 1. y grows downward. Horizontal circles
   project to ellipses with aspect RY; vertical distance projects by VC. */
const RY = 0.58, VC = 0.815;
const DEPTH = 0.62, WALL = 0.045, BROTH_D = 0.11, RIM_IN = 0.95;
const prof = u => 1 - 0.42 * Math.pow(u, 1.5);       // bowl radius vs depth fraction
const BR = { cx: 0, cy: VC * BROTH_D, rx: prof(BROTH_D / DEPTH) - WALL, ry: 0 };
BR.ry = BR.rx * RY;
function inBroth(x, y, m) {
  m = m || 0;
  const dx = x / (BR.rx - m), dy = (y - BR.cy) / (BR.ry - m * RY);
  return dx * dx + dy * dy < 1;
}
function envY(x) {                                     // lower silhouette of the bowl body
  let best = RY * Math.sqrt(Math.max(0, 1 - x * x));
  for (let k = 1; k <= 48; k++) {
    const u = k / 48, r = prof(u);
    if (Math.abs(x) < r) {
      const y = VC * DEPTH * u + r * RY * Math.sqrt(1 - x * x / (r * r));
      if (y > best) best = y;
    }
  }
  return best;
}

/* ---------------------------------------------------------------- state */
const canvas = document.getElementById('scene');
const ctx = canvas.getContext('2d');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let RM = mq.matches;
const S = { w: 1, h: 1, dpr: 1, R: 100, cx: 0, cy: 0, t: 0, px: 0, py: 0, flick: 1, hover: 0, warm: 0 };
const P = { x: 0, y: 0, nx: 0, ny: 0, sx: 9, sy: 9, vx: 0, vy: 0, has: false, down: false, lastT: 0, lastRip: 0, rx: 9, ry: 9 };

/* --------------------------------------------------------- draw helpers */
function ell(g, cx, cy, rx, ry, a0, a1, ccw) {
  g.beginPath(); g.ellipse(cx, cy, rx, ry, 0, a0 || 0, a1 === undefined ? TAU : a1, !!ccw);
}
function radialFill(g, cx, cy, rx, ry, stops, ox, oy, big) {
  g.save(); g.translate(cx, cy); g.scale(rx, ry);
  const gr = g.createRadialGradient(ox || 0, oy || 0, 0, 0, 0, 1);
  for (let i = 0; i < stops.length; i++) gr.addColorStop(stops[i][0], stops[i][1]);
  g.fillStyle = gr;
  if (big) g.fillRect(-1, -1, 2, 2); else { g.beginPath(); g.arc(0, 0, 1, 0, TAU); g.fill(); }
  g.restore();
}
function lgrad(g, x0, y0, x1, y1, stops) {
  const gr = g.createLinearGradient(x0, y0, x1, y1);
  for (let i = 0; i < stops.length; i++) gr.addColorStop(stops[i][0], stops[i][1]);
  return gr;
}
function rrect(g, x, y, w, h, r) {
  g.beginPath(); g.moveTo(x + r, y); g.lineTo(x + w - r, y); g.quadraticCurveTo(x + w, y, x + w, y + r);
  g.lineTo(x + w, y + h - r); g.quadraticCurveTo(x + w, y + h, x + w - r, y + h); g.lineTo(x + r, y + h);
  g.quadraticCurveTo(x, y + h, x, y + h - r); g.lineTo(x, y + r); g.quadraticCurveTo(x, y, x + r, y); g.closePath();
}
function smoothPath(g, pts, closed) {              // Catmull-Rom through points
  const n = pts.length; if (n < 2) return;
  g.moveTo(pts[0][0], pts[0][1]);
  for (let i = 0; i < (closed ? n : n - 1); i++) {
    const p0 = pts[(i - 1 + n) % n], p1 = pts[i], p2 = pts[(i + 1) % n], p3 = pts[(i + 2) % n];
    const c1x = p1[0] + (p2[0] - (closed || i > 0 ? p0[0] : p1[0])) / 6, c1y = p1[1] + (p2[1] - (closed || i > 0 ? p0[1] : p1[1])) / 6;
    const c2x = p2[0] - ((closed || i < n - 2 ? p3[0] : p2[0]) - p1[0]) / 6, c2y = p2[1] - ((closed || i < n - 2 ? p3[1] : p2[1]) - p1[1]) / 6;
    g.bezierCurveTo(c1x, c1y, c2x, c2y, p2[0], p2[1]);
  }
  if (closed) g.closePath();
}
/* offscreen sprite covering scene bounds [x0,x1]x[y0,y1] at device resolution */
function sprite(x0, y0, x1, y1, fn) {
  const sc = S.R * S.dpr, W = Math.max(1, Math.ceil((x1 - x0) * sc)), H = Math.max(1, Math.ceil((y1 - y0) * sc));
  const c = document.createElement('canvas'); c.width = W; c.height = H;
  const g = c.getContext('2d');
  g.setTransform(sc, 0, 0, sc, -x0 * sc, -y0 * sc);
  fn(g);
  return { c, x0, y0, w: W / sc, h: H / sc };
}
function blit(g, sp, x, y, rot, s, alpha) {
  g.save(); g.translate(x, y);
  if (rot) g.rotate(rot);
  if (s && s !== 1) g.scale(s, s);
  if (alpha !== undefined && alpha !== 1) g.globalAlpha *= alpha;
  g.drawImage(sp.c, sp.x0, sp.y0, sp.w, sp.h);
  g.restore();
}
