/* ------------------------------------------------------------- noodles */
function genStrands(n, cx, cy, rx, ry, r, len0, len1, wl, amp) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const pts = [];
    const a = r() * TAU, rad = Math.sqrt(r()) * 0.9;
    let x = cx + Math.cos(a) * rad * rx, y = cy + Math.sin(a) * rad * ry;
    let dir = r() * TAU;
    const len = len0 + r() * (len1 - len0), step = 0.014, ph = r() * TAU, turn = (r() - 0.5) * 3;
    const steps = Math.floor(len / step);
    for (let k = 0; k <= steps; k++) {
      const wob = Math.sin(k * step / wl * TAU + ph) * amp;
      pts.push([x + Math.cos(dir + PI / 2) * wob, y + Math.sin(dir + PI / 2) * wob]);
      dir += turn * step + noise3(x * 5, y * 5, i * 0.7) * 0.35;
      x += Math.cos(dir) * step; y += Math.sin(dir) * step * 0.8;
      const ex = (x - cx) / rx, ey = (y - cy) / ry;
      if (ex * ex + ey * ey > 1) dir = Math.atan2(-ey * ry, -ex * rx) + (r() - 0.5) * 1.4;
    }
    out.push({ pts, z: r() });
  }
  return out;
}
function strandPath(g, pts, ox, oy) {
  g.beginPath();
  const n = pts.length;
  g.moveTo(pts[0][0] + ox, pts[0][1] + oy);
  for (let i = 1; i < n - 1; i++) {
    const mx = (pts[i][0] + pts[i + 1][0]) / 2 + ox, my = (pts[i][1] + pts[i + 1][1]) / 2 + oy;
    g.quadraticCurveTo(pts[i][0] + ox, pts[i][1] + oy, mx, my);
  }
  g.lineTo(pts[n - 1][0] + ox, pts[n - 1][1] + oy);
}
function drawStrands(g, strands, st) {
  g.lineCap = 'round'; g.lineJoin = 'round';
  if (st.shadow) {
    g.strokeStyle = st.shadow; g.lineWidth = st.w * 1.7;
    for (let i = 0; i < strands.length; i++) { strandPath(g, strands[i].pts, 0.008, 0.012); g.stroke(); }
  }
  for (let i = 0; i < strands.length; i++) {
    const s = strands[i];
    strandPath(g, s.pts, 0, 0);
    g.strokeStyle = st.dark; g.lineWidth = st.w * 1.2; g.stroke();
    g.strokeStyle = s.mid || st.mid; g.lineWidth = st.w * 0.82; g.stroke();
    if (st.light) { strandPath(g, s.pts, -st.w * 0.16, -st.w * 0.22); g.strokeStyle = st.light; g.lineWidth = st.w * 0.22; g.stroke(); }
  }
}

/* --------------------------------------------------------------- caches */
const C = {};
const bodyP = new Path2D(), rimP = new Path2D(), brothP = new Path2D();
{
  bodyP.moveTo(-1, 0);
  for (let i = 0; i <= 140; i++) { const x = -1 + 2 * i / 140; bodyP.lineTo(x, envY(x)); }
  bodyP.ellipse(0, 0, 1, RY, 0, 0, PI, false); bodyP.closePath();
  rimP.ellipse(0, 0, 1, RY, 0, 0, TAU); rimP.ellipse(0, 0, RIM_IN, RIM_IN * RY, 0, 0, TAU);
  brothP.ellipse(BR.cx, BR.cy, BR.rx, BR.ry, 0, 0, TAU);
}

function buildGrain() {
  const W = canvas.width, H = canvas.height, d = S.dpr;
  const c = document.createElement('canvas'); c.width = W; c.height = H;
  const g = c.getContext('2d'), r = mulberry(77);
  const n = Math.round(H / (d * 5)) + 10;
  g.lineCap = 'round';
  for (let i = 0; i < n; i++) {
    const y0 = (i + r()) / n * H, dark = r() < 0.72;
    const amp = (1.5 + r() * 7) * d, wl = (260 + r() * 600) * d, ph = r() * TAU, f2 = r() * 0.02 + 0.006;
    g.beginPath();
    for (let k = 0; k <= 40; k++) {
      const x = k / 40 * W, y = y0 + Math.sin(x / wl + ph) * amp + noise3(x * f2 / d, i * 2.3, 0.5) * 4 * d;
      if (k === 0) g.moveTo(x, y); else g.lineTo(x, y);
    }
    g.strokeStyle = dark ? 'rgba(0,0,0,' + (0.10 + r() * 0.22).toFixed(3) + ')' : 'rgba(255,205,150,' + (0.025 + r() * 0.05).toFixed(3) + ')';
    g.lineWidth = (dark ? 0.6 + r() * 1.8 : 0.5 + r() * 0.9) * d;
    g.stroke();
  }
  C.grain = c;
}

function buildBowl() {
  C.bowl = sprite(-1.06, -0.64, 1.06, 1.0, g => {
    const r = mulberry(31);
    /* exterior body */
    g.save(); g.clip(bodyP);
    g.fillStyle = lgrad(g, -1, 0, 1, 0, [[0, '#5b5450'], [0.3, '#3b3839'], [0.62, '#232326'], [1, '#101013']]);
    g.fillRect(-1.1, -0.1, 2.2, 1.2);
    g.fillStyle = lgrad(g, 0, 0.55, 0, 0.94, [[0, 'rgba(0,0,0,0)'], [1, 'rgba(0,0,0,0.55)']]);
    g.fillRect(-1.1, 0.5, 2.2, 0.6);
    radialFill(g, 0.05, 0.99, 0.95, 0.32, [[0, 'rgba(255,150,70,0.42)'], [1, 'rgba(255,150,70,0)']]);
    for (let k = 2; k < 47; k += 2) {                       /* throwing lines */
      const u = k / 48, rad = prof(u), yc = VC * DEPTH * u;
      ell(g, 0, yc, rad, rad * RY, 0.06, PI - 0.06); g.strokeStyle = 'rgba(255,255,255,0.045)'; g.lineWidth = 0.0035; g.stroke();
      ell(g, 0, yc + 0.004, rad, rad * RY, 0.06, PI - 0.06); g.strokeStyle = 'rgba(0,0,0,0.09)'; g.stroke();
    }
    for (let i = 0; i < 900; i++) {                          /* stoneware speckle */
      const x = -1 + r() * 2, y = r() * 0.95;
      if (y > envY(x) || y < RY * Math.sqrt(Math.max(0, 1 - x * x))) continue;
      g.fillStyle = r() < 0.4 ? 'rgba(255,240,220,' + (0.03 + r() * 0.06).toFixed(3) + ')' : 'rgba(0,0,0,' + (0.06 + r() * 0.12).toFixed(3) + ')';
      g.beginPath(); g.arc(x, y, 0.003 + r() * 0.006, 0, TAU); g.fill();
    }
    ell(g, 0, 0.02, 1, RY, 0, PI); g.strokeStyle = 'rgba(160,92,48,0.45)'; g.lineWidth = 0.07; g.stroke();   /* rust glaze break */
    ell(g, 0, 0.012, 1, RY, 0, PI); g.strokeStyle = 'rgba(190,120,70,0.35)'; g.lineWidth = 0.03; g.stroke();
    for (let i = 0; i < 7; i++) {                             /* glaze drips */
      const a = 0.15 + r() * (PI - 0.3), x = Math.cos(a), y0 = Math.sin(a) * RY + 0.02, L = 0.05 + r() * 0.12;
      g.fillStyle = 'rgba(150,85,45,' + (0.25 + r() * 0.3).toFixed(2) + ')';
      g.beginPath(); g.moveTo(x - 0.012, y0); g.quadraticCurveTo(x - 0.014, y0 + L * 0.7, x, y0 + L); g.quadraticCurveTo(x + 0.014, y0 + L * 0.7, x + 0.012, y0); g.closePath(); g.fill();
    }
    for (let i = 0; i < 5; i++) {                             /* rim overhang shadow */
      ell(g, 0, 0.012 + i * 0.007, 1, RY, 0, PI); g.strokeStyle = 'rgba(0,0,0,' + (0.24 - i * 0.045).toFixed(3) + ')'; g.lineWidth = 0.014; g.stroke();
    }
    g.restore();
    /* interior wall */
    g.save(); ell(g, 0, 0, RIM_IN, RIM_IN * RY); g.clip();
    g.fillStyle = lgrad(g, -0.95, -0.3, 0.95, 0.2, [[0, '#ece1c8'], [0.5, '#d8c7a6'], [1, '#b3a081']]);
    g.fillRect(-1, -0.6, 2, 1.2);
    radialFill(g, 0, 0, RIM_IN, RIM_IN * RY, [[0, 'rgba(60,35,15,0)'], [0.72, 'rgba(60,35,15,0)'], [1, 'rgba(60,35,15,0.55)']]);
    g.fillStyle = lgrad(g, 0, -0.56, 0, -0.36, [[0, 'rgba(45,28,14,0.6)'], [1, 'rgba(45,28,14,0)']]);
    g.fillRect(-1, -0.6, 2, 0.3);
    radialFill(g, BR.cx, BR.cy, BR.rx * 1.14, BR.ry * 1.14, [[0, 'rgba(225,125,45,0.6)'], [0.86, 'rgba(225,125,45,0.6)'], [1, 'rgba(225,125,45,0)']]);
    g.restore();
    /* broth */
    g.save(); g.clip(brothP);
    radialFill(g, BR.cx, BR.cy, BR.rx, BR.ry, [[0, '#eba648'], [0.42, '#d7842f'], [0.8, '#b4631f'], [1, '#8a4414']], -0.2, -0.12);
    for (let i = 0; i < 16; i++) radialFill(g, (r() - 0.5) * 1.6, BR.cy + (r() - 0.5) * 0.9, 0.1 + r() * 0.22, 0.06 + r() * 0.13, [[0, 'rgba(255,205,125,0.17)'], [1, 'rgba(255,205,125,0)']]);
    const sub = genStrands(26, 0, BR.cy + 0.02, 0.72, 0.44, mulberry(5), 0.35, 0.7, 0.07, 0.013);
    drawStrands(g, sub, { dark: 'rgba(150,95,35,0.7)', mid: 'rgba(242,198,112,0.8)', w: 0.024 });
    g.fillStyle = 'rgba(214,130,47,0.6)'; g.fillRect(-1, -0.6, 2, 1.3);
    for (let i = 0; i < 110; i++) {                           /* miso specks */
      g.fillStyle = 'rgba(105,52,14,' + (0.12 + r() * 0.22).toFixed(2) + ')';
      g.beginPath(); g.ellipse((r() - 0.5) * 1.7, BR.cy + (r() - 0.5) * 1.0, 0.003 + r() * 0.005, 0.002 + r() * 0.003, r() * PI, 0, TAU); g.fill();
    }
    for (let i = 0; i < 7; i++) {                             /* edge occlusion */
      ell(g, BR.cx, BR.cy, BR.rx - i * 0.007, BR.ry - i * 0.007 * RY); g.strokeStyle = 'rgba(85,38,10,' + (0.32 - i * 0.042).toFixed(3) + ')'; g.lineWidth = 0.014; g.stroke();
    }
    ell(g, BR.cx, BR.cy, BR.rx - 0.012, BR.ry - 0.012 * RY, 1.12 * PI, 1.88 * PI);
    g.strokeStyle = 'rgba(255,228,185,0.5)'; g.lineWidth = 0.007; g.stroke();
