}

function buildRim() {
  C.rim = sprite(-1.03, -0.62, 1.03, 0.62, g => {
    const r = mulberry(19);
    g.save(); g.clip(rimP, 'evenodd');
    g.fillStyle = lgrad(g, -0.9, -0.5, 0.9, 0.5, [[0, '#706962'], [0.35, '#494544'], [0.7, '#2b2a2c'], [1, '#18181b']]);
