    }
    for (let i = 0; i < 220; i++) {
      const a = r() * TAU, rad = RIM_IN + r() * (1 - RIM_IN);
      g.fillStyle = r() < 0.5 ? 'rgba(255,240,220,' + (0.04 + r() * 0.08).toFixed(3) + ')' : 'rgba(0,0,0,' + (0.08 + r() * 0.15).toFixed(3) + ')';
      g.beginPath(); g.arc(Math.cos(a) * rad, Math.sin(a) * rad * RY, 0.002 + r() * 0.004, 0, TAU); g.fill();
    }
