  for (let i = 0; i < 8; i++) radialFill(g, (r() - 0.5) * w * 0.9, (r() - 0.5) * h * 0.9, 0.03 + r() * 0.06, 0.02 + r() * 0.035, [[0, 'rgba(188,115,42,0.62)'], [0.6, 'rgba(188,115,42,0.32)'], [1, 'rgba(188,115,42,0)']]);
  g.strokeStyle = 'rgba(72,38,12,0.5)'; g.lineWidth = 0.009; g.lineCap = 'round';
  for (let i = 0; i < 2; i++) { const x = -w / 2 + 0.07 + i * 0.09; g.beginPath(); g.moveTo(x, -h / 2 + 0.012); g.lineTo(x + 0.03, h / 2 - 0.012); g.stroke(); }
  for (let i = 0; i < 45; i++) { g.fillStyle = 'rgba(120,80,40,0.16)'; g.beginPath(); g.arc((r() - 0.5) * w, (r() - 0.5) * h, 0.002 + r() * 0.004, 0, TAU); g.fill(); }
  g.restore();
