  g.beginPath(); g.moveTo(-w / 2 + 0.02, -h / 2 + 0.003); g.lineTo(w / 2 - 0.02, -h / 2 + 0.003);
  g.strokeStyle = 'rgba(255,252,240,0.55)'; g.lineWidth = 0.005; g.stroke();
