function drawBokChoy(g, seed) {
  const r = mulberry(seed), bx = -0.21, by = 0;
  const stems = [[0.03, -0.075], [0.05, -0.035], [0.06, 0.01], [0.05, 0.05], [0.03, 0.085]];
  for (let i = 0; i < stems.length; i++) {                     /* leaves */
    const ex = stems[i][0], ey = stems[i][1], ang = Math.atan2(ey - by, ex - bx);
    g.save(); g.translate(ex - 0.015, ey); g.rotate(ang + (r() - 0.5) * 0.35);
    const L = 0.17 + r() * 0.06, W = 0.058 + r() * 0.022;
    const leaf = () => { g.beginPath(); g.moveTo(0, 0); g.bezierCurveTo(L * 0.3, -W, L * 0.85, -W * 0.9, L, 0); g.bezierCurveTo(L * 0.85, W * 0.9, L * 0.3, W, 0, 0); g.closePath(); };
    leaf(); g.fillStyle = lgrad(g, 0, 0, L, 0, [[0, '#86c25a'], [0.5, '#3f9538'], [1, '#2a6c2b']]); g.fill();
    g.save(); leaf(); g.clip(); radialFill(g, L * 0.4, -W * 0.3, L * 0.6, W * 0.8, [[0, 'rgba(255,255,255,0.22)'], [1, 'rgba(255,255,255,0)']]); g.restore();
    leaf(); g.strokeStyle = 'rgba(22,66,24,0.55)'; g.lineWidth = 0.004; g.stroke();
    g.beginPath(); g.moveTo(0, 0); g.quadraticCurveTo(L * 0.5, W * 0.05, L * 0.92, 0);
    g.strokeStyle = 'rgba(225,245,200,0.55)'; g.lineWidth = 0.005; g.stroke();
    g.restore();
  }
  for (let i = 0; i < stems.length; i++) {                     /* stems */
    const ex = stems[i][0], ey = stems[i][1], mx = bx + (ex - bx) * 0.5;
    const stem = () => { g.beginPath(); g.moveTo(bx, by); g.quadraticCurveTo(mx, ey - 0.04, ex, ey - 0.02); g.quadraticCurveTo(ex + 0.02, ey, ex, ey + 0.02); g.quadraticCurveTo(mx, ey + 0.04, bx, by); g.closePath(); };
    stem(); g.fillStyle = lgrad(g, bx, 0, ex, 0, [[0, '#f0f4e2'], [0.6, '#d6e6bc'], [1, '#b5d197']]); g.fill();
    g.strokeStyle = 'rgba(105,140,80,0.5)'; g.lineWidth = 0.004; g.stroke();
    g.beginPath(); g.moveTo(bx + 0.02, by); g.quadraticCurveTo(mx, ey - 0.012, ex - 0.012, ey);
    g.strokeStyle = 'rgba(255,255,255,0.4)'; g.lineWidth = 0.005; g.stroke();
  }
}

function drawShiitake(g, seed) {
