    g.strokeStyle = 'rgba(30,14,5,0.28)'; g.lineWidth = 0.003; g.beginPath();
    g.moveTo(Math.cos(a) * d * rx, Math.sin(a) * d * ry); g.lineTo(Math.cos(a) * (d + 0.25) * rx, Math.sin(a) * (d + 0.25) * ry); g.stroke();
