  for (let i = 0; i < 4; i++) { const a = pts[i], b = pts[(i + 1) % 4]; for (let k = 0; k < 8; k++) { const t = k / 8; poly.push([lerp(a[0], b[0], t) + (r() - 0.5) * 0.007, lerp(a[1], b[1], t) + (r() - 0.5) * 0.007]); } }
