573	function spawnSteam(n, x, y, boost, seed) {
574	  for (let i = 0; i < n; i++) {
575	    let px, py, sd = seed === undefined ? rnd() * 100 : seed + (rnd() - 0.5) * 0.3;
576	    if (x === undefined) { const a = rnd() * TAU, d = Math.pow(rnd(), 0.6) * 0.8; px = Math.cos(a) * d * BR.rx; py = BR.cy + Math.sin(a) * d * BR.ry; }
577	    else { px = x + (rnd() - 0.5) * 0.08; py = y + (rnd() - 0.5) * 0.05; }
578	    if (STEAM.length >= MAXS) STEAM.shift();
579	    const wisp = seed !== undefined;
580	    STEAM.push({ x: px, y: py, vx: (rnd() - 0.5) * 0.04, vy: -(0.14 + rnd() * 0.1) * (1 + (boost || 0)), life: 0, max: 3.6 + rnd() * 2.8,
581	      size: (wisp ? 0.05 : 0.07) + rnd() * 0.06, alpha: (wisp ? 0.1 : 0.05) + rnd() * 0.08, seed: sd, fi: boost ? 0.3 : 1.3 });
582	  }
583	}
584	function updateSteam(dt) {
585	  const t = S.t, has = P.has, boost = (1 + S.warm * 0.45) * S.q;
586	  for (let i = 0; i < EMIT.length; i++) {
587	    const e = EMIT[i];
588	    e.a += noise3(e.seed, t * 0.06, 1.5) * 0.35 * dt; e.d = clamp(e.d + noise3(e.seed + 5, t * 0.06, 2.5) * 0.15 * dt, 0.15, 0.75);
589	    e.acc += e.rate * boost * dt;
590	    while (e.acc >= 1) { e.acc -= 1; spawnSteam(1, Math.cos(e.a) * e.d * BR.rx, BR.cy + Math.sin(e.a) * e.d * BR.ry, 0, e.seed); }
591	  }
592	  ST.acc += 9 * boost * dt;
593	  while (ST.acc >= 1) { ST.acc -= 1; spawnSteam(1); }
594	  for (let i = STEAM.length - 1; i >= 0; i--) {
595	    const p = STEAM[i]; p.life += dt;
596	    if (p.life >= p.max) { STEAM[i] = STEAM[STEAM.length - 1]; STEAM.pop(); continue; }
597	    const n1 = noise3(p.x * 2.2 + p.seed, p.y * 2.2, t * 0.3), n2 = noise3(p.x * 2.2 + 31, p.y * 2.2 + p.seed, t * 0.3 + 9);
598	    p.vx += n1 * 0.4 * dt; p.vy += (n2 * 0.2 - 0.14) * dt;
599	    if (has) {
600	      const dx = p.x - P.sx, dy = p.y - P.sy, d = Math.hypot(dx, dy) + 1e-4, rad = 0.46;
601	      if (d < rad) { const s = 1 - d / rad, s2 = s * s; p.vx += (dx / d) * s2 * 1.7 * dt + P.vx * s * 0.9 * dt; p.vy += (dy / d) * s2 * 1.7 * dt + P.vy * s * 0.9 * dt; }
602	    }
603	    const dmp = Math.exp(-dt * 0.75); p.vx *= dmp; p.vy *= dmp;
604	    p.x += p.vx * dt; p.y += p.vy * dt; p.size += 0.055 * dt;
605	  }
