630	function updateFloat(dt) {
631	  const t = S.t, has = P.has;
632	  for (let i = 0; i < FLOAT.length; i++) {
633	    const f = FLOAT[i];
634	    const cx = f.x, cy = (f.y - 0.1) / RY, d = Math.hypot(cx, cy) + 1e-4;
635	    const tvx = (-cy / d) * 0.012 + noise3(f.x * 2, f.y * 2, t * 0.12) * 0.012;
