637	    f.vx += (tvx - f.vx) * dt * 0.8; f.vy += (tvy - f.vy) * dt * 0.8;
638	    if (has) {
639	      const px = f.x - P.sx, py = (f.y - P.sy) / RY, pd = Math.hypot(px, py) + 1e-4, rad = 0.2 + Math.min(0.2, Math.hypot(P.vx, P.vy) * 0.08);
640	      if (pd < rad) { const s = 1 - pd / rad, s2 = s * s; f.vx += (px / pd) * s2 * 1.0 * dt + P.vx * s * 0.15 * dt; f.vy += (py / pd) * RY * s2 * 1.0 * dt + P.vy * s * 0.15 * dt; }
641	    }
