643	    for (let k = 0; k < RIPS.length; k++) {
644	      const rp = RIPS[k], rx = f.x - rp.x, ry = (f.y - rp.y) / RY, rd = Math.hypot(rx, ry) + 1e-4, dd = rd - rp.r;
