646	    }
647	    f.bob = bob;
648	    f.x += f.vx * dt; f.y += f.vy * dt; f.rot += (f.vr + f.vx * 2) * dt;
649	    const ex = f.x / (BR.rx - f.size - 0.03), ey = (f.y - BR.cy) / (BR.ry - (f.size + 0.03) * RY), e2 = ex * ex + ey * ey;

650	    if (e2 > 1) { f.vx -= ex * dt * 0.7; f.vy -= ey * RY * dt * 0.7; if (e2 > 1.25) { f.x *= 0.98; f.y = BR.cy + (f.y - BR.cy) * 0.98; } }
651	    const qx = f.x / (RIM_IN - f.size - 0.04), qy = f.y / ((RIM_IN - f.size - 0.04) * RY), q2 = qx * qx + qy * qy;
