653	    const mx = f.x / 0.5, my = (f.y - 0.08) / 0.33, m2 = mx * mx + my * my;
654	    if (m2 < 1) { const mm = Math.sqrt(m2) + 1e-4; f.vx += (mx / mm) * dt * 0.5; f.vy += (my / mm) * RY * dt * 0.5; }
655	    const dmp = Math.exp(-dt * 1.2); f.vx *= dmp; f.vy *= dmp; f.vr *= dmp;
656	  }
