754	S.pulse = 0; S.jig = 0; S.q = 1; S.ema = 1 / 60;
755	function update(dt) {
756	  S.t += dt;
757	  S.ema += (dt - S.ema) * 0.05;
758	  if (S.ema > 1 / 38) S.q = Math.max(0.45, S.q - 0.02); else if (S.ema < 1 / 55) S.q = Math.min(1, S.q + 0.004);
759	  S.flick = RM ? 1 : 1 + 0.035 * Math.sin(S.t * 1.7) + 0.02 * Math.sin(S.t * 4.3 + 1.3) + 0.012 * Math.sin(S.t * 9.7 + 0.4) + noise3(S.t * 0.8, 3.3, 7.1) * 0.03;
760	  const k = RM ? 1 : 1 - Math.exp(-dt * 3.5);
761	  S.px += ((P.has ? P.nx : 0) - S.px) * k; S.py += ((P.has ? P.ny : 0) - S.py) * k;
762	  const hv = P.has && Math.hypot(P.sx / 1.15, (P.sy - 0.15) / 0.9) < 1 ? 1 : 0;
763	  S.warm += (hv - S.warm) * (RM ? 1 : 1 - Math.exp(-dt * 2));
764	  S.pulse *= Math.exp(-dt * 2.2); S.jig *= Math.exp(-dt * 2.6);
765	  const vd = Math.exp(-dt * 6); P.vx *= vd; P.vy *= vd;
766	  if (!RM) { updateSteam(dt); updateFloat(dt); updateRipples(dt); updateMotes(dt); }
767	}
